/**
 * Saved career-resilience reports (gap #103) — read use cases for
 * routes/career.ts. The report itself is generated by the
 * `career-resilience` AI tool (services/ai-tools/tools/career.ts).
 */
import { getDb } from "../../db/index.js";
import {
  CareerResilienceRepository,
  type CareerResilienceReportRow,
} from "../../repositories/careerResilienceRepository.js";

const repo = () => new CareerResilienceRepository(getDb());

/** The caller's most recent reports. */
export function listResilienceReports(userId: string): Promise<CareerResilienceReportRow[]> {
  return repo().listForUser(userId);
}

/** Public share-link view: the report without its owner id, or null. */
export async function findSharedResilienceReport(
  token: string,
): Promise<Omit<CareerResilienceReportRow, "userId"> | null> {
  const report = await repo().findByShareToken(token);
  if (!report) return null;
  const { userId: _uid, ...publicReport } = report;
  return publicReport;
}
